import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { PersonFill } from 'react-bootstrap-icons'; // Assuming react-bootstrap-icons is installed
import { useAuth } from '../../context/AuthContext';   // Import AuthContext
import { useMessage } from '../../context/MessageContext'; // Import MessageContext
import { resumeApi } from '../../api/api';             // Import your API utility
import '../../styles/ApplyPage.css';                       // Import its specific CSS
import 'bootstrap-icons/font/bootstrap-icons.css';     // Ensure icons are available

function ApplyPage() { // Retaining original name 'ApplyPage' as per your request
  const navigate = useNavigate();
  const { currentUser, logout } = useAuth(); // Get currentUser and logout function from AuthContext
  const { setMessage, setLoading } = useMessage(); // Get message and loading setters from MessageContext

  const [file, setFile] = useState(null);
  const [extractedSkills, setExtractedSkills] = useState(''); // State for skills input
  const [resumeSummary, setResumeSummary] = useState('');     // State for summary textarea

  // Handler for file input change
  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
    setMessage(''); // Clear message when a new file is selected
  };

  // Handler for form submission (resume upload)
  const handleSubmit = async () => { // Made async to await API call
    setMessage(''); // Clear any previous messages
    setLoading(true); // Set global loading to true

    if (!file) {
      setMessage('Please select a PDF file to upload.'); // Use global message for validation
      setLoading(false);
      return;
    }

    // Create FormData object to send file and other data
    const formData = new FormData();
    formData.append('username', currentUser?.username); // Get username from AuthContext
    formData.append('file', file); // Append the selected file
    formData.append('extractedSkills', extractedSkills); // Append skills string
    formData.append('resumeSummary', resumeSummary);     // Append summary string

    try {
      // Call the resume upload API using your centralized api utility
      const result = await resumeApi.uploadResume(formData);

      setMessage(result.message || 'Resume uploaded successfully!'); // Set global success message
      // Clear form fields after successful submission
      setFile(null); // Reset file state
      setExtractedSkills('');
      setResumeSummary('');
      // To visually clear the file input, you'd typically need to reset the form
      // or make the input an uncontrolled component and use a ref.
      // For now, setting 'file' to null clears the state.
    } catch (error) {
      // Catch and display error message from the API or network
      setMessage('Failed to upload resume: ' + error.message);
      console.error('Resume upload error:', error);
    } finally {
      setLoading(false); // Set global loading to false
    }
  };

  // Handler for logout button
  const handleLogout = () => {
    logout(); // This calls the logout function from AuthContext
    navigate('/login'); // Redirect to login page after logging out
  };

  return (
    <div className="applypage-wrapper">
      <div className="background"></div> {/* Uses global background styling */}
      <nav className="navbar">
        <div className="navbar-left">
          <i className="bi bi-briefcase-fill logo-icon"></i>
          <span className="logo-text">hire.in</span>
        </div>
        <div className="navbar-right">
          {/* Use Link component for navigation and onClick for logout action */}
          <Link to="/" className="logout-btn" onClick={handleLogout}>
            <span className="logout-text">Logout</span>
            <PersonFill size={18} />
          </Link>
        </div>
      </nav>
      <div className="resume-content">
        <h2>Upload Your Resume</h2> {/* Updated title for clarity */}
        <p className="upload-instruction"><i className="bi bi-cloud-arrow-up"></i> Boost your career – Upload your resume now!</p><br />

        <div className="upload-form-box"> {/* Wrapper for form elements */}
          {/* Custom file input using a label */}
          <label htmlFor="resume-file-input" className="custom-file-upload">
            <i className="bi bi-file-earmark-arrow-up"></i> {file ? file.name : 'Choose PDF File'}
          </label>
          <input
            id="resume-file-input"
            type="file"
            accept=".pdf" // Restrict to PDF files
            onChange={handleFileChange}
            style={{ display: 'none' }} // Hide the actual input
          />

          {/* New input for skills */}
          <input
            type="text"
            placeholder="Key Skills (comma-separated)"
            value={extractedSkills}
            onChange={(e) => setExtractedSkills(e.target.value)}
          />
          {/* New textarea for resume summary */}
          <textarea
            placeholder="Resume Summary/Keywords"
            value={resumeSummary}
            onChange={(e) => setResumeSummary(e.target.value)}
            rows="4" // Set initial rows
          ></textarea>

          <button onClick={handleSubmit} className="submit-btn">
            Submit Resume
          </button>
        </div>
      </div>
    </div>
  );
}
export default ApplyPage;
